/* FitFirst prototype — setup: settings (14 areas), pitch kit, FitFirst platform console */
(function () {
  const FF = window.FF, U = FF.ui, esc = FF.esc, $ = FF.$, R = FF.ROLES, T = FF.TAX;
  const TABS = [['store', 'Store'], ['staff', 'Staff & roles'], ['devices', 'Devices'], ['racks', 'Racks'], ['taxonomy', 'Categories & sizes'], ['rules', 'Styling rules'], ['billing', 'Billing'], ['pos', 'Billing software'], ['tryon', 'Try-on'], ['privacy', 'Privacy'], ['notify', 'WhatsApp'], ['plan', 'Plan & usage'], ['audit', 'Audit log'], ['demo', 'Demo controls']];
  const save = (what, ent, det) => { FF.audit(what, ent, det); FF.save(); FF.render(); FF.toast('Saved', 'ok'); };
  const row = (title, sub, ctl) => `<div class="row" style="padding:12px 0;border-bottom:1px solid var(--line)"><div class="grow"><b>${title}</b>${sub ? `<div class="small muted">${sub}</div>` : ''}</div>${ctl}</div>`;
  const P = {
    store: () => { const st = FF.store(), s = FF.db.settings; return `<form data-submit="st-store" class="card grid g2 stack">${U.field('Shop name', `<input name="name" required value="${esc(st.name)}">`, 'Shown on the kiosk, bills and shared lookbooks')}${U.field('Area', `<input name="area" required value="${esc(st.area)}">`)}${U.field('Phone', `<input name="phone" required value="${esc(st.phone)}">`)}${U.field('GSTIN', `<input name="gstin" value="${esc(st.gstin)}" pattern="[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]" data-msg="15 characters, e.g. 24ABCDE1234F1Z5">`)}${U.field('GST registration', `<select name="reg">${[['REGULAR', 'Regular — Tax Invoice'], ['COMPOSITION', 'Composition — Bill of Supply'], ['NONE', 'Unregistered — receipt']].map(([v, l]) => `<option value="${v}" ${st.reg === v ? 'selected' : ''}>${l}</option>`).join('')}</select>`)}${U.field('Cost as % of MRP', `<input name="cost" type="number" min="10" max="95" required value="${s.costRatio}">`, 'Used to value aged stock without exposing real cost prices')}${U.field('Shopper languages', `<div class="row wrap">${FF.LANGS.map((l) => `<label class="check"><input type="checkbox" name="l_${l[0]}" ${s.langs.includes(l[0]) ? 'checked' : ''}> ${l[1]}</label>`).join('')}</div>`)}${U.field('Services', `<label class="check"><input type="checkbox" name="stitch" ${s.stitching ? 'checked' : ''}> We offer stitching for unstitched pieces</label>`)}<div><button class="btn btn-p">Save changes</button></div></form>`; },
    staff: () => { const me = FF.me(), areas = [['Live queue, visits, record a sale', 1, 1, 1, 0], ['Billing counter', 1, 1, 1, 0], ['Discount above limit, refunds', 1, 1, 0, 0], ['Intake, review, count, labels', 1, 1, 0, 1], ['Results, clearance, demand gaps', 1, 1, 0, 0], ['Lock pilot thresholds, change plan', 1, 0, 0, 0], ['Settings and staff PINs', 1, 1, 0, 0]];
      return `<div class="row between mb8"><p class="small muted">Each person signs in with their own PIN, so sales carry a name and a leaver can be switched off in one tap.</p><button class="btn btn-p btn-s" data-act="st-staff-edit">${FF.icon('plus')} Add person</button></div>${U.table('staff', [{ k: 'n', l: 'Name', html: (s) => `<div class="row"><span class="avatar">${esc(s.code)}</span><b>${esc(s.name)}</b>${s.id === me.id ? ' ' + U.badge('You', 'ink') : ''}</div>` }, { k: 'r', l: 'Role', html: (s) => T.roles[s.role] }, { k: 'p', l: 'Phone', html: (s) => `<span class="mono small">${esc(s.phone)}</span>` }, { k: 'c', l: 'Code on bills', html: (s) => `<span class="mono">${esc(s.code)}</span>` }, { k: 's', l: 'Status', html: (s) => U.badge(s.active ? 'Active' : 'Switched off', s.active ? 'ok' : '') }, { k: 'a', l: '', html: (s) => `<div class="row gap6" style="justify-content:flex-end"><button class="btn btn-s" data-act="st-staff-edit" data-id="${s.id}">Edit</button><button class="btn btn-s" data-act="st-pin" data-id="${s.id}">Reset PIN</button><button class="btn btn-s ${s.active ? 'btn-d' : ''}" data-act="st-staff-off" data-id="${s.id}">${s.active ? 'Switch off' : 'Switch on'}</button></div>` }], FF.db.staff)}
        <h3 class="mt24 mb8">What each role can do</h3><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Area</th><th>Owner</th><th>Manager</th><th>Sales staff</th><th>Intake</th></tr></thead><tbody>${areas.map((a) => `<tr><td>${a[0]}</td>${a.slice(1).map((x) => `<td>${x ? '<span class="ok b">✓</span>' : '<span class="muted">—</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`; },
    devices: () => `<div class="row between mb8"><p class="small muted">Every tablet, kiosk and counter is enrolled with a one-time code. A lost device is revoked here and stops working at once.</p><button class="btn btn-p btn-s" data-act="st-dev-new">${FF.icon('plus')} Enrol a device</button></div><div class="grid g2 stack">${FF.db.devices.map((d) => { const stale = Date.now() - d.seen > 6 * 3600000, cal = d.calib ? (d.calib < Date.now() ? ['Calibration expired', 'bad'] : ['Calibrated · ' + Math.ceil((d.calib - Date.now()) / FF.DAY) + ' days left', 'ok']) : null; return `<div class="card" style="${d.active ? '' : 'opacity:.55'}"><div class="row between"><b>${esc(d.name)}</b>${U.badge(d.active ? (stale ? 'Not seen for ' + FF.ago(d.seen) : 'Online') : 'Revoked', d.active ? (stale ? 'warn' : 'ok') : 'bad')}</div><div class="small muted mt4">${FF.cap(d.kind.toLowerCase())} · app ${d.ver} · last seen ${FF.ago(d.seen)} ago</div>${cal ? `<div class="mt8">${U.badge(cal[0], cal[1])}</div>` : ''}<div class="row mt12">${d.active && ['KIOSK', 'INTAKE_STATION'].includes(d.kind) ? `<button class="btn btn-s" data-act="st-calib" data-id="${d.id}">${FF.icon('camera')} Calibrate</button>` : ''}<button class="btn btn-s ${d.active ? 'btn-d' : ''}" data-act="st-dev-revoke" data-id="${d.id}">${d.active ? 'Revoke' : 'Re-enable'}</button></div></div>`; }).join('')}</div>`,
    racks: () => `<p class="small muted mb8">Rack and shelf codes are what let a salesperson walk straight to a piece.</p><div class="card"><div class="row wrap">${FF.db.racks.map((r) => { const n = FF.db.products.filter((p) => p.rack === r).length; return `<span class="chip mono">${r} <span class="muted" style="font-family:var(--sans)">${n}</span>${n ? '' : `<button class="x" style="width:22px;height:22px" data-act="st-rack-del" data-r="${r}" aria-label="Remove ${r}">×</button>`}</span>`; }).join('')}</div><form data-submit="st-rack" class="row mt16" style="max-width:360px"><input name="code" required pattern="[A-Za-z]{1,2}[0-9]{1,2}-[A-Za-z][0-9]{1,2}" placeholder="e.g. R7-S1" style="text-transform:uppercase" data-msg="Use a code like R7-S1 (rack 7, shelf 1)"><button class="btn">Add</button></form><p class="tiny muted mt8">A rack can be removed only when no piece is on it.</p></div>`,
    taxonomy: () => `<p class="small muted mb8">Categories are data, not code: each one carries its size system, the photos intake asks for, and how fast it ages. Regional garments can be added without a software change.</p>${Object.entries(T.groups).map(([gk, g]) => `<div class="card mb8"><div class="row between wrap"><h3>${g.name}</h3><span class="small muted">Sizes: ${g.size === 'FREE' ? 'free size' : T.sizes[g.size].join(' · ')}</span></div><div class="row wrap mt8">${Object.entries(T.cats).filter(([, c]) => c.group === gk).map(([k, c]) => `<span class="chip">${esc(c.name)}${c.custom ? ' <span class="badge b-brass">yours</span>' : ''}</span>`).join('')}</div><dl class="kv small mt12"><dt>Quick intake</dt><dd>${g.quick.join(' + ')}</dd><dt>Full intake</dt><dd>${g.full.join(' · ')}</dd><dt>Ages as</dt><dd>${g.aging} wear · ${FF.db.settings.aging[g.aging].join(' → ')} days</dd><dt>Try-on</dt><dd>${g.tryon ? 'Available' : 'Not yet — below the quality bar'}</dd></dl></div>`).join('')}<div class="card"><h3>Add a category of your own</h3><form data-submit="st-cat" class="grid g4 mt12" style="align-items:end">${U.field('Name', '<input name="name" required maxlength="24" placeholder="e.g. Chaniya choli">')}${U.field('Group', `<select name="group">${Object.entries(T.groups).map(([k, g]) => `<option value="${k}">${g.name}</option>`).join('')}</select>`)}${U.field('Section', `<select name="dept">${Object.entries(T.depts).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select>`)}<button class="btn btn-p">Add category</button></form></div>`,
    rules: () => { const db = FF.db, draft = db.rulesets.find((r) => r.status === 'DRAFT'), labels = { colour: 'Colour', sil: 'Cut vs fit goals', prop: 'Proportion', occ: 'Occasion', pref: 'Shopper likes' };
      return `<p class="small muted mb8">“AI sees, rules decide.” The rules that judge what suits whom are written down, versioned and signed off by a stylist. An active ruleset is never edited — it is cloned, changed and activated.</p><div class="card pad0 mb16">${db.rulesets.slice().reverse().map((r) => `<div class="row" style="padding:12px 16px;border-bottom:1px solid var(--line)"><div class="grow"><b class="mono">${esc(r.ver)}</b> ${U.badge(FF.cap(r.status.toLowerCase()), r.status === 'ACTIVE' ? 'ok' : r.status === 'DRAFT' ? 'warn' : '')}<div class="small muted">${esc(r.note)} · ${esc(r.by)} · ${FF.fmtDate(r.at)}</div></div>${r.status === 'ACTIVE' && !draft ? `<button class="btn btn-s" data-act="st-rule-clone">Clone to a draft</button>` : ''}${r.status === 'DRAFT' ? `<button class="btn btn-s" data-act="st-rule-drop">Discard</button><button class="btn btn-s btn-p" data-act="st-rule-activate">Activate…</button>` : ''}</div>`).join('')}</div>
        <div class="card"><div class="row between wrap"><h3>How much each thing counts ${draft ? U.badge('Editing draft ' + draft.ver, 'warn') : ''}</h3><span class="small muted">per category group · each row adds up to 100</span></div><div class="tbl-wrap mt12" style="border:0"><table class="tbl"><thead><tr><th>Group</th>${Object.values(labels).map((l) => `<th class="r">${l}</th>`).join('')}<th class="r">Total</th></tr></thead><tbody>${Object.entries(T.groups).map(([gk, g]) => { const w = (draft && draft.w && draft.w[gk]) || g.w, tot = Math.round(FF.sum(Object.values(w)) * 100); return `<tr><td>${g.name}</td>${Object.keys(labels).map((k) => `<td class="r">${draft ? `<input type="number" min="0" max="100" step="5" value="${Math.round(w[k] * 100)}" data-change="st-w" data-lazy data-g="${gk}" data-k="${k}" style="width:68px;text-align:right" aria-label="${g.name} ${labels[k]}">` : Math.round(w[k] * 100)}</td>`).join('')}<td class="r b ${tot === 100 ? 'ok' : 'bad'}">${tot}</td></tr>`; }).join('')}</tbody></table></div></div>
        <div class="card mt16"><h3>Example rules in this version</h3><div class="tbl-wrap mt12" style="border:0"><table class="tbl"><tbody>${[['Drapes', 'Petite + broad border or large motifs', '−', 'Thin borders elongate a petite frame'], ['Drapes', 'Goal “streamline the middle” + flowing georgette, chiffon or crepe', '+', 'Flowing fabric skims the middle'], ['Ethnic tops', 'Goal “balance hips” + A-line or anarkali', '+', 'A-line cut balances your hips'], ['Ethnic tops', 'Goal “define waist” + kaftan', '−', '(never shown to the shopper)'], ['Lehenga', 'Tall + broad border', '+', 'Broad border carries well on your height'], ['All', 'Warm undertone + maroon, rust, mustard, olive, gold', '+', 'Maroon brings out your warm undertone'], ['All', 'Garment colour too close to skin tone and low in colour', '−', 'Washout guard']].map((r) => `<tr><td class="small muted">${r[0]}</td><td>${r[1]}</td><td class="b ${r[2] === '+' ? 'ok' : 'bad'}">${r[2]}</td><td class="small">${r[3]}</td></tr>`).join('')}</tbody></table></div><p class="tiny muted mt8">Explanations are fixed templates in English, Hindi and Gujarati. Undertone can move the colour score by at most 0.3.</p></div>`; },
    billing: () => { const b = FF.db.settings.billing; return `<div class="grid g2 stack"><form data-submit="st-bill" class="card col"><h3>Counter</h3>${U.field('Invoice series for this counter', `<input name="series" required pattern="[A-Z0-9]{1,4}" value="${esc(b.series)}" style="text-transform:uppercase" data-msg="1–4 letters or digits">`, `Bills are numbered ${esc(b.series)}/26-27/00001 onward. One series per counter means offline bills never collide; numbering restarts each 1 April.`)}${U.field('Discount a salesperson may give without a manager (%)', `<input name="disc" type="number" min="0" max="50" required value="${b.discLimit}">`)}${U.field('UPI ID for the payment QR', `<input name="upi" required pattern="[A-Za-z0-9._-]+@[A-Za-z]+" value="${esc(b.upi)}" data-msg="Looks like name@bank">`)}${U.field('Receipt printer', `<select name="printer">${['58mm thermal', '80mm thermal', 'A5 invoice (laser/inkjet)'].map((x) => `<option ${b.printer === x ? 'selected' : ''}>${x}</option>`).join('')}</select>`)}<div><button class="btn btn-p">Save</button></div></form>
      <div class="col gap16"><div class="card"><div class="row between"><h3>Tax rules</h3><button class="btn btn-s" data-act="st-tax">${FF.icon('plus')} New rule</button></div><p class="small muted">Rates change, so they are data with effective dates.</p>${FF.db.taxRules.map((t) => `<div style="padding:10px 0;border-bottom:1px solid var(--line)"><div class="row between"><b>HSN ${esc(t.hsn)} · ${esc(t.desc)}</b>${U.badge(t.active ? 'In force' : 'Scheduled', t.active ? 'ok' : 'warn')}</div><div class="small muted">${esc(t.slabs)} · from ${esc(t.from)}</div></div>`).join('')}<p class="note small mt12">Before the first live bill, the shop's CA reviews these rules and the bill formats. ${U.badge('CA review: pending', 'warn')}</p></div>
      <div class="card"><h3>Supported hardware</h3><dl class="kv small mt8"><dt>Receipt printer</dt><dd>2–3 tested 58/80 mm thermal models · about ₹3–6k</dd><dt>Label printer</dt><dd>Tested 2-inch models · about ₹8–15k</dd><dt>Scanner</dt><dd>Any USB or Bluetooth keyboard-mode scanner · ₹1.5–3k</dd><dt>If the printer fails</dt><dd>Send the WhatsApp e-bill or a PDF instead</dd></dl></div></div></div>`; },
    pos: () => { const p = FF.db.settings.pos, lv = [['L0', 'Manual', 'Staff record sales in FitFirst. Always available as the fallback.'], ['L1', 'Daily Excel / CSV', 'Export a file from the billing software and upload it. Works with almost everything.'], ['L2', 'Bridge on the billing PC', 'A small read-only program sends sales every ~15 minutes (Tally, Marg, Busy).'], ['L3', 'Cloud connection', 'Live link to Zoho, Shopify POS, Ginesys or GoFrugal. Premium.']];
      return `<div class="card"><h3>How does this shop bill?</h3><div class="mt12">${U.seg('st-path', [['A', 'Path A — we work with their billing software'], ['B', 'Path B — FitFirst Billing is the billing software']], p.path)}</div><p class="small muted mt8">${p.path === 'A' ? "The cashier types the shopper's FitFirst code into the bill's remarks or narration. That one habit links sales in any software." : 'The cashier scans the shopper\'s QR at the counter. Stock, bills and attribution live in one place. The CA still gets Tally and GSTR-1 exports.'}</p></div>
      ${p.path === 'A' ? `<div class="grid g2 stack mt16">${lv.map(([k, t, dsc]) => `<button class="card" style="text-align:left;${p.level === k ? 'border-color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)' : ''}" data-act="st-level" data-v="${k}" aria-pressed="${p.level === k}"><div class="row between"><b>${k} · ${t}</b>${p.level === k ? U.badge('In use', 'ok') : ''}</div><div class="small muted mt4">${dsc}</div></button>`).join('')}</div>
        <div class="card mt16">${row('Billing software', 'Decides which saved column template is offered first', `<select data-change="st-kind" style="width:auto">${['Tally Prime', 'Vyapar', 'Marg', 'Busy', 'Other / generic'].map((k) => `<option ${p.kind === k ? 'selected' : ''}>${k}</option>`).join('')}</select>`)}${row('The billing software owns stock quantities', 'When on, a sale recorded in FitFirst only reserves the piece; the imported bill confirms it. That prevents counting a sale twice.', U.switch('st-auth', p.authority))}${p.level === 'L2' ? row('Bridge agent', 'Windows service · outbound HTTPS only · never writes to the billing software', `<button class="btn btn-s" data-act="st-agent">Get install code</button>`) : ''}${row('Last sync', FF.fmtDT(p.lastSync), `<a class="btn btn-s" href="#/import">Open import & sync</a>`)}</div>` : `<div class="note n-ok mt16">FitFirst Billing is on. <a class="link" href="#/billing">Open the counter</a> · <a class="link" href="#/settings/billing">Billing settings</a>. Switching a shop over: import items and opening stock, print missing labels, run in parallel with the old system for a week, then cut over on a quiet day — never during a festival or wedding peak.</div>`}`; },
    tryon: () => { const t = FF.db.settings.tryon, jobs = FF.db.tryons, pass = { drapes: 84, ethnic: 82, lehenga: 81, mens: 80, wtops: 71, wbottoms: 0, dresses: 68, kids: 0 };
      return `<div class="grid g2 stack"><div class="card">${row('“See it on me” for shoppers', 'Always from a phone, adults only, with two separate consents', U.switch('st-try', t.enabled, 'data-k="enabled"'))}${row('Emergency stop', 'Pauses all new previews at once, e.g. if costs jump or the provider misbehaves', U.switch('st-try', t.kill, 'data-k="kill"'))}${row('Previews per visit', 'Staff can add 3 more for a shopper', `<input type="number" min="1" max="10" value="${t.perVisit}" data-change="st-try-n" data-lazy style="width:72px">`)}<div class="mt16"><div class="row between small"><span>This month</span><b>${t.used} of ${t.monthly} previews</b></div><div class="meter mt4"><i style="width:${Math.min(100, (t.used / t.monthly) * 100)}%;background:${t.used / t.monthly > 0.85 ? 'var(--bad)' : 'var(--ink)'}"></i></div><p class="tiny muted mt8">About ₹6–7 a preview. A slot is reserved when the shopper taps and only counted when a preview passes its checks.</p></div></div>
        <div class="card"><h3>Categories</h3><p class="small muted">A category goes live only when 80% or more of its test previews pass the quality rubric.</p>${Object.entries(T.groups).map(([k, g]) => row(g.name, pass[k] ? `${pass[k]}% pass on the evaluation set` : 'No evaluation set yet', pass[k] >= 80 ? U.switch('st-try-cat', t.cats.includes(k), `data-k="${k}"`) : U.badge('Below the bar', ''))).join('')}</div></div>
        <div class="card mt16"><h3>Checks every preview must pass</h3><div class="grid g4 mt12 small">${[['Skin tone unchanged', 'Colour shift within tolerance and never lighter — a colourism guard'], ['One person', 'Exactly one figure in the result'], ['True garment colour', 'Matches the measured colour of the real piece'], ['Body unchanged', 'Shoulder and hip width within 5%']].map(([a, b]) => `<div><b>${a}</b><div class="muted">${b}</div></div>`).join('')}</div><p class="tiny muted mt12">A failed preview is regenerated once, then withheld. Every result carries a visible “AI-generated preview” label and embedded metadata.</p></div>
        <h3 class="mt24 mb8">Recent previews</h3>${U.table('tryjobs', [{ k: 'at', l: 'When', html: (j) => FF.fmtDT(j.at) }, { k: 'c', l: 'Visit', html: (j) => `<span class="code small">${j.code}</span>` }, { k: 'p', l: 'Piece', html: (j) => esc((FF.prod(j.pid) || {}).name) }, { k: 's', l: 'Result', html: (j) => U.badge(j.status === 'DELIVERED' ? 'Delivered' : 'Withheld — failed checks', j.status === 'DELIVERED' ? 'ok' : 'warn') }, { k: 'ms', l: 'Time', r: 1, html: (j) => (j.ms ? (j.ms / 1000).toFixed(0) + ' s' : '—') }, { k: 'cost', l: 'Cost', r: 1, html: (j) => (j.cost ? '₹' + j.cost.toFixed(2) : 'Not charged') }, { k: 'e', l: 'Photo deleted by', html: (j) => (j.expires ? FF.fmtDT(j.expires) : '—') }], jobs, { per: 6, empty: U.empty('spark', 'No previews yet', 'Open a visit on the phone and tap “See it on me”.', `<a class="btn btn-s" href="phone.html" target="_blank" rel="noopener">Open the phone lookbook</a>`) })}`; },
    privacy: () => { const r = FF.db.settings.retention, db = FF.db; return `<div class="note n-info mb16">Under India's DPDP Act the <b>shop</b> decides how shopper data is used and FitFirst processes it on the shop's behalf. Full obligations apply from 13 May 2027. Nothing on this screen replaces a review by a qualified lawyer.</div>
      <div class="grid g2 stack"><form data-submit="st-ret" class="card col"><h3>How long data is kept</h3>${U.field('Visit answers and picks (days)', `<input name="visitDays" type="number" min="1" max="365" required value="${r.visitDays}">`, 'Deleted automatically after this')}${U.field('Try-on photos (hours)', `<input name="tryonHours" type="number" min="1" max="24" required value="${r.tryonHours}">`, 'Never more than 24')}${U.field('Bills (months)', `<input value="${r.billsMonths}" disabled>`, 'Fixed by GST law — kept even if a shopper asks for deletion')}<div><button class="btn btn-p">Save</button></div></form>
        <div class="card"><h3>Delete a shopper's data</h3><p class="small muted">For a request made at the counter. Shoppers can also do this themselves from their phone.</p><form data-submit="st-erase" class="row top mt12"><div class="field grow"><input name="code" required pattern="[Ff]{0,2}-?[A-Za-z0-9]{4}" placeholder="Visit code, e.g. FF-7K2Q" style="font-family:var(--mono);text-transform:uppercase" data-msg="Codes look like FF-7K2Q"></div><button class="btn btn-d">Erase</button></form><h4 class="mt16">Erasure log</h4>${db.erasures.slice(0, 5).map((e) => `<div class="small" style="padding:6px 0;border-bottom:1px solid var(--line)"><b class="code">${e.code}</b> · ${esc(e.by)} · ${FF.fmtDT(e.at)}</div>`).join('') || '<p class="small muted mt8">No erasures yet.</p>'}</div></div>
      <div class="grid g2 stack mt16"><div class="card"><div class="row between"><h3>Privacy notice</h3><button class="btn btn-s" data-act="st-notice">Publish a new version</button></div>${db.notices.map((n) => `<div class="row between small" style="padding:8px 0;border-bottom:1px solid var(--line)"><span><b class="mono">${n.ver}</b> · ${n.lang}</span><span class="muted">in force from ${FF.fmtDate(n.from)}</span></div>`).join('')}<p class="tiny muted mt8">Each consent records which notice version and language the shopper saw.</p></div>
        <div class="card"><h3>If something goes wrong</h3><ol class="small" style="padding-left:18px;margin:8px 0 0;display:flex;flex-direction:column;gap:4px"><li>Revoke the affected device or sign-in (Devices, Staff).</li><li>Tell FitFirst support — we pause the affected service.</li><li>Record what was exposed and for whom.</li><li>Notify the Data Protection Board and affected shoppers within the legal deadline.</li></ol><dl class="kv small mt12"><dt>Complaints contact</dt><dd>${esc(FF.store().phone)} · privacy@suvarnasilks.example</dd><dt>Processing agreement</dt><dd>${U.badge('Signed with FitFirst', 'ok')} ${U.badge('AI provider: paid tier, no training', 'ok')}</dd></dl></div></div>
      <h3 class="mt24 mb8">Consent record</h3>${U.table('consent', [{ k: 'at', l: 'When', sort: (c) => c.at, html: (c) => FF.fmtDT(c.at) }, { k: 'c', l: 'Visit', html: (c) => `<span class="code small">${c.code}</span>` }, { k: 'p', l: 'Purpose', html: (c) => esc(c.purpose) }, { k: 'g', l: 'Answer', html: (c) => U.badge(c.granted ? 'Agreed' : 'Declined', c.granted ? 'ok' : '') }, { k: 'n', l: 'Notice', html: (c) => `<span class="mono small">${c.notice} · ${c.lang}</span>` }, { k: 'm', l: 'How', html: (c) => `<span class="small">${esc(c.method)}</span>` }], db.consents, { per: 6, empty: U.empty('shield', 'No consents recorded yet', 'Each consultation writes one row per purpose here.') })}`; },
    notify: () => { const w = FF.db.settings.whatsapp; return `<div class="card" style="max-width:640px">${row('Daily summary on WhatsApp', 'Consultations, purchases, aged stock cleared, the top demand gap and the top seller', U.switch('st-wa', w.summary))}<form data-submit="st-wa-save" class="grid g2 mt16">${U.field('Send to', `<input name="to" type="tel" required pattern="[6-9][0-9 ]{9,11}" value="${esc(w.to)}" data-msg="Enter a mobile number">`)}${U.field('At', `<input name="time" type="time" required value="${w.time}">`)}<div class="row"><button class="btn btn-p">Save</button><button type="button" class="btn" data-act="i-wa">Preview the message</button></div></form><p class="note n-plain small mt16">Messages to shoppers (offers, reminders) are a separate decision and need their explicit opt-in. The only shopper message today is the single “it has arrived” note they ask for.</p></div>`; },
    plan: () => { const db = FF.db, live = db.products.filter((p) => p.status === 'LIVE').length, t = db.settings.tryon, plans = [['LITE', 'Lite · QR Stylist', '₹1,499–2,499', ['Phone-first flow for shoppers', 'Staff app and owner results', 'About 1,000 live styles, AI tagging', 'Manual and Excel sales link', 'FitFirst Billing as an add-on']], ['PRO', 'Pro · Assisted / Kiosk', '₹3,999–5,999 + hardware', ['Everything in Lite', 'Assisted and kiosk modes, calibrated tone', 'Clearance controls, lookbook sharing', 'About 100 try-ons a month', 'FitFirst Billing included']], ['PREMIUM', 'Premium', '₹9,999+', ['Everything in Pro', 'Tally bridge and cloud billing links', 'Multi-store and transfers', 'About 300 try-ons a month', 'WhatsApp summaries, priority support']]];
      return `<p class="note small mb16">Plans and prices are <b>hypotheses to test</b> in the pilot and the first pitches. Nothing here has been offered to a shop.</p><div class="grid g3">${[['Live styles', live, 1000], ['Try-ons this month', t.used, t.monthly], ['Enrolled devices', db.devices.filter((d) => d.active).length, 6]].map(([l, v, m]) => `<div class="kpi"><div class="k-l">${l}</div><div class="k-v">${v}<span class="small muted"> / ${m}</span></div><div class="meter mt8"><i style="width:${Math.min(100, (v / m) * 100)}%"></i></div></div>`).join('')}</div>
        <div class="grid g3 mt16">${plans.map(([k, n, pr, f]) => `<div class="plan ${db.org.plan === k ? 'cur' : ''}"><div class="row between"><h3>${n}</h3>${db.org.plan === k ? U.badge('Current', 'ink') : ''}</div><div class="serif" style="font-size:22px">${pr}<span class="small muted"> / month</span></div><ul>${f.map((x) => `<li>${x}</li>`).join('')}</ul>${db.org.plan === k ? '' : `<button class="btn mt8" data-act="st-plan" data-v="${k}">Switch to ${n.split(' ·')[0]}</button>`}</div>`).join('')}</div>
        <h3 class="mt24 mb8">Add-ons</h3><div class="card">${[['Extra try-ons', '₹10–15 each, in packs', 'packs'], ['We photograph and tag your stock', '₹10–25 a piece, or a monthly retainer', 'managed'], ['AI catalogue photos', 'On-model images of your stock for Instagram · ₹15–30 an image', 'photos'], ['Hardware on rent', 'Tablet stand and light, or a kiosk · ₹1,500–3,000 a month', 'hw']].map(([a, b, k]) => row(a, b, U.switch('st-addon', (db.org.addons || []).includes(k), `data-k="${k}"`))).join('')}</div>`; },
    audit: () => `<p class="small muted mb8">Who changed what, and when. Privileged actions cannot be removed from this list.</p>${U.table('audit', [{ k: 'at', l: 'When', sort: (a) => a.at, html: (a) => FF.fmtDT(a.at) }, { k: 'w', l: 'Who', html: (a) => esc(a.who) }, { k: 'a', l: 'Action', html: (a) => `<b>${esc(a.action)}</b>` }, { k: 'e', l: 'On', html: (a) => esc(a.entity) }, { k: 'd', l: 'Detail', html: (a) => `<span class="small muted">${esc(a.detail)}</span>` }], FF.db.audit, { per: 12 })}<button class="btn mt12" data-act="st-audit-x">${FF.icon('download')} Export</button>`,
    demo: () => { const f = FF.db.settings.flags; let size = 0; try { size = (localStorage.getItem('ff_proto_v5') || '').length; } catch (e) {} return `<div class="note mb16">These switches exist only in the prototype, so you can see how each surface behaves when something goes wrong.</div><div class="grid g2 stack"><div class="card"><h3>Scenarios</h3>${[['offline', 'Internet is down', 'Kiosk recommends from saved stock; billing keeps its own number series; try-on switches off'], ['aiOff', 'AI tagging is failing', 'A loud banner appears and intake falls back to manual entry — never a silent guess'], ['camDenied', 'Camera permission denied', 'The kiosk offers swatches instead'], ['lowLight', 'Poor lighting at the kiosk', 'The camera admits it is unsure and asks the shopper to pick'], ['tryonFail', 'Try-on fails its quality checks', 'Regenerates once, then withholds the image and does not charge']].map(([k, a, b]) => row(a, b, U.switch('st-flag', f[k], `data-k="${k}"`))).join('')}</div>
      <div class="card"><h3>Data</h3><p class="small muted">Everything is stored in this browser only (${Math.round(size / 1024)} KB). All figures are synthetic.</p><div class="col mt12"><button class="btn" data-act="sim-walkin">${FF.icon('plus')} Simulate a shopper finishing a consultation</button><button class="btn" data-act="st-unlock">Unlock the pilot thresholds (demo only)</button><button class="btn" data-act="st-onb">Replay first-time setup at next owner sign-in</button><button class="btn btn-d" data-act="st-reset">${FF.icon('refresh')} Reset all demo data</button></div></div></div>`; },
  };
  FF.page('settings', { title: 'Settings', icon: 'settings', roles: R.MGR, render: (tab) => { tab = P[tab] ? tab : 'store'; return `<div class="ph1"><div><h1>Settings</h1></div></div>${U.tabs('st-tab', TABS, tab)}<div class="mt16">${P[tab]()}</div>`; } });
  FF.act('st-tab', (d) => FF.go('#/settings/' + d.v));
  FF.act('st-store', (f) => { const st = FF.store(), s = FF.db.settings; Object.assign(st, { name: f.name, area: f.area, phone: f.phone, gstin: f.gstin, reg: f.reg }); s.costRatio = f.cost; s.stitching = f.stitch; s.langs = FF.LANGS.map((l) => l[0]).filter((l) => f['l_' + l]); if (!s.langs.length) s.langs = ['en']; save('Updated store details', st.name); });
  /* staff */
  FF.act('st-staff-edit', (d) => { const s = d.id ? FF.db.staff.find((x) => x.id === d.id) : { name: '', role: 'STAFF', phone: '', code: '' }; FF.modal({ title: d.id ? 'Edit ' + esc(s.name) : 'Add a person', size: 'narrow', body: `<form id="sf" data-submit="st-staff-save" class="col"><input type="hidden" name="id" value="${d.id || ''}">${U.field('Full name', `<input name="name" required minlength="3" value="${esc(s.name)}">`)}${U.field('Role', `<select name="role">${Object.entries(T.roles).map(([k, v]) => `<option value="${k}" ${s.role === k ? 'selected' : ''}>${v}</option>`).join('')}</select>`)}${U.field('Mobile', `<input name="phone" type="tel" required pattern="[6-9][0-9 ]{9,11}" value="${esc(s.phone)}" data-msg="Enter a mobile number">`)}${U.field('Staff code on bills', `<input name="code" required pattern="[A-Za-z]{2,3}" maxlength="3" value="${esc(s.code)}" style="text-transform:uppercase" data-msg="2 or 3 letters">`, "Matches the salesperson code in the shop's billing software")}${d.id ? '' : U.field('Starting PIN', '<input name="pin" required pattern="[0-9]{4}" maxlength="4" inputmode="numeric" data-msg="Exactly 4 digits">', 'They should change it on first sign-in')}</form>`, footer: `<button class="btn" data-act="close">Cancel</button><button class="btn btn-p" form="sf">Save</button>` }); });
  FF.act('st-staff-save', (f) => { const db = FF.db, code = f.code.toUpperCase(); if (db.staff.some((s) => s.code === code && s.id !== f.id)) return FF.toast('Another person already uses code ' + code, 'bad'); if (f.id) { const s = db.staff.find((x) => x.id === f.id); if (s.role === 'OWNER' && f.role !== 'OWNER' && db.staff.filter((x) => x.role === 'OWNER' && x.active).length < 2) return FF.toast('The shop needs at least one owner', 'bad'); Object.assign(s, { name: f.name, role: f.role, phone: f.phone, code }); } else db.staff.push({ id: FF.uid('u'), name: f.name, role: f.role, phone: f.phone, code, pin: f.pin, active: true }); FF.closeOverlay(); save(f.id ? 'Edited staff' : 'Added staff', f.name, T.roles[f.role]); });
  FF.act('st-pin', (d) => { const s = FF.db.staff.find((x) => x.id === d.id), pin = String(1000 + Math.floor(Math.random() * 9000)); FF.confirm('Reset PIN for ' + esc(s.name) + '?', 'Their current PIN stops working at once.', 'Reset PIN', () => { s.pin = pin; FF.audit('Reset PIN', 'Staff', s.name); FF.save(); FF.modal({ title: 'New PIN for ' + esc(s.name), size: 'narrow', body: `<div class="center"><div class="bigcode code" style="font-size:44px;letter-spacing:.2em">${pin}</div><p class="small muted mt12">Shown once. Tell them in person; they will be asked to change it.</p></div>`, footer: `<button class="btn btn-p" data-act="close">Done</button>` }); }); });
  FF.act('st-staff-off', (d) => { const s = FF.db.staff.find((x) => x.id === d.id); if (s.active && s.id === FF.me().id) return FF.toast('You cannot switch off your own account', 'bad'); if (s.active && s.role === 'OWNER' && FF.db.staff.filter((x) => x.role === 'OWNER' && x.active).length < 2) return FF.toast('The shop needs at least one owner', 'bad'); const run = () => { s.active = !s.active; save(s.active ? 'Switched on' : 'Switched off', 'Staff', s.name); }; s.active ? FF.confirm('Switch off ' + esc(s.name) + '?', 'They can no longer sign in. Their past sales stay in their name.', 'Switch off', run, true) : run(); });
  /* devices */
  FF.act('st-dev-new', () => FF.modal({ title: 'Enrol a device', size: 'narrow', body: `<form data-submit="st-dev-code" class="col">${U.field('Name', '<input name="name" required maxlength="30" placeholder="e.g. Counter tablet 2">')}${U.field('Type', `<select name="kind"><option value="ASSISTED_TABLET">Assisted tablet</option><option value="KIOSK">Kiosk</option><option value="BILLING_COUNTER">Billing counter</option><option value="INTAKE_STATION">Intake station</option></select>`)}<button class="btn btn-p">Get pairing code</button></form>` }));
  FF.act('st-dev-code', (f) => { const code = Array.from({ length: 6 }, () => 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[Math.floor(Math.random() * 32)]).join(''); FF._dev = f; FF.reOverlay({ title: 'Pair “' + esc(f.name) + '”', body: `<div class="center"><p class="small muted">On the new device open <span class="mono">fitfirst.app/pair</span> and type:</p><div class="bigcode code mt12" style="font-size:44px">${code}</div><p class="tiny muted mt12">Valid for 10 minutes, usable once.</p><button class="btn btn-p mt16" data-act="st-dev-pair">Simulate the device pairing</button></div>` }); });
  FF.act('st-dev-pair', () => { const f = FF._dev; FF.db.devices.push({ id: FF.uid('d'), name: f.name, kind: f.kind, seen: Date.now(), ver: '2.3.1', active: true, calib: f.kind === 'KIOSK' ? Date.now() - 1 : null }); FF.closeOverlay(); save('Enrolled device', f.name, f.kind); });
  FF.act('st-dev-revoke', (d) => { const x = FF.db.devices.find((y) => y.id === d.id), run = () => { x.active = !x.active; save(x.active ? 'Re-enabled device' : 'Revoked device', x.name); }; x.active ? FF.confirm('Revoke ' + esc(x.name) + '?', 'It stops working immediately and must be paired again to come back.', 'Revoke', run, true) : run(); });
  FF.act('st-calib', (d) => { FF._cal = { id: d.id, step: 0 }; calib(); });
  const calib = () => { const c = FF._cal, steps = [['Light on', 'Switch on the LED panel and wait a minute for it to settle. Close any curtain that lets daylight onto the shopper’s position.'], ['Grey card', 'Hold the grey reference card where a shopper’s face would be, filling the box on screen.'], ['Lock the camera', 'FitFirst locks exposure and white balance so every shopper is read the same way.']], o = { title: 'Calibrate · step ' + (c.step + 1) + ' of 3', body: `<h3>${steps[c.step][0]}</h3><p class="mt8">${steps[c.step][1]}</p>${c.step === 1 ? `<div class="cam-box mt16" style="aspect-ratio:16/9;background:#2a2622;border-radius:10px;display:grid;place-items:center"><div style="width:30%;aspect-ratio:1;background:#808080;border:2px dashed #fff"></div></div>` : ''}${c.step === 2 ? `<dl class="kv small mt16"><dt>Grey read</dt><dd>Y = 0.18 ✓</dd><dt>White balance</dt><dd>Locked at 5,300 K ✓</dd><dt>Exposure</dt><dd>Locked ✓</dd></dl>` : ''}`, footer: `<button class="btn" data-act="close">Cancel</button><button class="btn btn-p" data-act="st-calib-next">${c.step === 2 ? 'Save calibration' : 'Next'}</button>`, size: 'narrow' }; $('.modal') ? FF.reOverlay(o) : FF.modal(o); };
  FF.act('st-calib-next', () => { const c = FF._cal; if (c.step < 2) { c.step++; return calib(); } const d = FF.db.devices.find((x) => x.id === c.id); d.calib = Date.now() + 30 * FF.DAY; FF.closeOverlay(); save('Calibrated camera', d.name, 'valid 30 days'); });
  /* racks, taxonomy */
  FF.act('st-rack', (f) => { const c = f.code.toUpperCase(); if (FF.db.racks.includes(c)) return FF.toast(c + ' already exists', 'bad'); FF.db.racks.push(c); FF.db.racks.sort(); save('Added rack', c); });
  FF.act('st-rack-del', (d) => { FF.db.racks = FF.db.racks.filter((r) => r !== d.r); save('Removed rack', d.r); });
  FF.act('st-cat', (f) => { const key = f.name.toLowerCase().replace(/[^a-z0-9]+/g, '_'); if (T.cats[key] || Object.values(T.cats).some((c) => c.name.toLowerCase() === f.name.toLowerCase())) return FF.toast('That category already exists', 'bad'); const shape = Object.values(T.cats).find((c) => c.group === f.group).shape; (FF.db.customCats = FF.db.customCats || []).push({ key, name: f.name, group: f.group, dept: f.dept, shape }); FF.applyOverrides(); save('Added category', f.name, T.groups[f.group].name); });
  /* rules */
  FF.act('st-rule-clone', () => { const a = FF.db.rulesets.find((r) => r.status === 'ACTIVE'), n = FF.db.rulesets.length, w = {}; Object.entries(T.groups).forEach(([k, g]) => { w[k] = Object.assign({}, g.w); }); FF.db.rulesets.push({ ver: '2026.11-draft-' + n, status: 'DRAFT', by: FF.me().name, at: Date.now(), note: 'Cloned from ' + a.ver, w }); save('Cloned ruleset', a.ver); });
  FF.onChange('st-w', (v, el) => { const d = FF.db.rulesets.find((r) => r.status === 'DRAFT'), n = FF.clamp(Math.round(+v || 0), 0, 100); d.w[el.dataset.g][el.dataset.k] = n / 100; FF.save(); FF.render(); });
  FF.act('st-rule-drop', () => FF.confirm('Discard this draft?', 'The active ruleset is not affected.', 'Discard', () => { FF.db.rulesets = FF.db.rulesets.filter((r) => r.status !== 'DRAFT'); save('Discarded ruleset draft', 'Rules'); }, true));
  FF.act('st-rule-activate', () => { const d = FF.db.rulesets.find((r) => r.status === 'DRAFT'), bad = Object.entries(d.w).find(([, w]) => Math.round(FF.sum(Object.values(w)) * 100) !== 100); if (bad) return FF.toast(`${T.groups[bad[0]].name} must add up to 100`, 'bad'); FF.managerPin('Activating a ruleset changes every recommendation from now on. Past visits keep the version they were made with.', () => { FF.db.rulesets.forEach((r) => { if (r.status === 'ACTIVE') r.status = 'ARCHIVED'; }); d.status = 'ACTIVE'; d.ver = d.ver.replace('draft', 'shop'); d.note += ' · activated'; FF.db.ruleW = d.w; FF.db.settings.ruleset = d.ver; FF.applyOverrides(); save('Activated ruleset', d.ver); }); });
  /* billing + pos */
  FF.act('st-bill', (f) => { Object.assign(FF.db.settings.billing, { series: f.series.toUpperCase(), discLimit: f.disc, upi: f.upi, printer: f.printer }); save('Updated billing settings', 'Counter'); });
  FF.act('st-tax', () => FF.modal({ title: 'New tax rule', size: 'narrow', body: `<form id="tf" data-submit="st-tax-save" class="col"><p class="small muted">A new rule is scheduled, not live, until its date — and the CA should see it first.</p>${U.field('HSN chapter or prefix', '<input name="hsn" required pattern="[0-9–-]{2,8}" placeholder="e.g. 61–62" data-msg="Digits, e.g. 62 or 61–62">')}${U.field('Applies to', '<input name="desc" required maxlength="40">')}${U.field('Rate rule', '<input name="slabs" required placeholder="e.g. 5% up to ₹2,500 · 12% above">')}${U.field('In force from', `<input name="from" type="date" required min="${FF.day(Date.now() + FF.DAY)}">`)}</form>`, footer: `<button class="btn" data-act="close">Cancel</button><button class="btn btn-p" form="tf">Schedule rule</button>` }));
  FF.act('st-tax-save', (f) => { FF.db.taxRules.push({ id: FF.uid('t'), hsn: f.hsn, desc: f.desc, slabs: f.slabs, from: FF.fmtDate(new Date(f.from)), active: false }); FF.closeOverlay(); save('Scheduled tax rule', f.hsn, f.slabs); });
  FF.act('st-path', (d) => { FF.db.settings.pos.path = d.v; save('Billing path → ' + d.v, 'POS'); });
  FF.act('st-level', (d) => { if (d.v === 'L3' && FF.db.org.plan !== 'PREMIUM') return FF.modal({ title: 'Cloud connections are part of Premium', size: 'narrow', body: '<p>A live link to Zoho, Shopify POS, Ginesys or GoFrugal is built when a paying shop needs it, on the Premium plan.</p>', footer: `<button class="btn" data-act="close">Close</button><button class="btn btn-p" data-act="go" data-to="#/settings/plan">See plans</button>` }); FF.db.settings.pos.level = d.v; save('Sync level → ' + d.v, 'POS'); });
  FF.onChange('st-kind', (v) => { FF.db.settings.pos.kind = v; save('Billing software → ' + v, 'POS'); });
  FF.act('st-auth', () => { const p = FF.db.settings.pos; p.authority = !p.authority; save('Stock authority → ' + (p.authority ? 'billing software' : 'FitFirst'), 'POS'); });
  FF.act('st-agent', () => FF.modal({ title: 'Install the bridge', size: 'narrow', body: `<ol class="small" style="padding-left:18px;display:flex;flex-direction:column;gap:6px"><li>On the billing PC (Windows 10 or later) download <span class="mono">fitfirst-bridge.msi</span>.</li><li>Enter this code when asked: <b class="code">BR-${String(FF.hash(FF.store().name)).slice(0, 6)}</b></li><li>In Tally, switch on the ODBC/HTTP server on port 9000.</li></ol><p class="note n-plain small mt12">The bridge only reads. It never writes to the billing software and only makes outbound connections.</p>`, footer: `<button class="btn btn-p" data-act="close">Done</button>` }));
  /* try-on, privacy, notify, plan */
  FF.act('st-try', (d) => { const t = FF.db.settings.tryon; t[d.k] = !t[d.k]; save((d.k === 'kill' ? 'Try-on emergency stop ' : 'Try-on ') + (t[d.k] ? 'on' : 'off'), 'Try-on'); });
  FF.onChange('st-try-n', (v) => { const n = Math.round(+v); if (!(n >= 1 && n <= 10)) { FF.toast('Between 1 and 10', 'bad'); return FF.render(); } FF.db.settings.tryon.perVisit = n; save('Try-ons per visit → ' + n, 'Try-on'); });
  FF.act('st-try-cat', (d) => { const c = FF.db.settings.tryon.cats, i = c.indexOf(d.k); i < 0 ? c.push(d.k) : c.splice(i, 1); T.groups[d.k].tryon = i < 0; save('Try-on ' + (i < 0 ? 'enabled' : 'disabled') + ' for ' + T.groups[d.k].name, 'Try-on'); });
  FF.act('st-ret', (f) => { Object.assign(FF.db.settings.retention, { visitDays: f.visitDays, tryonHours: f.tryonHours }); save('Changed retention', 'Privacy', `${f.visitDays} d · ${f.tryonHours} h`); });
  FF.act('st-erase', (f) => { const code = 'FF-' + f.code.toUpperCase().replace(/^FF-?/, ''), v = FF.db.visits.find((x) => x.code === code); if (!v) return FF.toast('No visit with code ' + code, 'bad'); if (v.erased) return FF.toast(code + ' was already erased', 'warn'); FF.confirm('Erase ' + code + '?', 'Removes the answers, picks and try-ons. Bills are kept as the law requires. This is logged and cannot be undone.', 'Erase', () => { Object.assign(v, { erased: true, erasedAt: Date.now(), profiles: [], picks: [], shortlist: [], events: [] }); FF.db.tryons = FF.db.tryons.filter((x) => x.code !== code); FF.db.erasures.unshift({ at: Date.now(), code, by: FF.me().name + ' (counter request)', scope: 'Visit profile, picks, try-ons' }); save('Erased shopper data', code); }, true); });
  FF.act('st-notice', () => FF.confirm('Publish notice version N-4?', 'New consultations will show and record the new version in all three languages. Earlier consents keep the version they were given under. Have the wording reviewed first.', 'Publish N-4', () => { ['English', 'हिन्दी', 'ગુજરાતી'].forEach((l) => FF.db.notices.unshift({ ver: 'N-' + (4 + Math.floor(FF.db.notices.length / 3) - 1), lang: l, from: Date.now() })); save('Published privacy notice', 'Privacy'); }));
  FF.act('st-wa', () => { const w = FF.db.settings.whatsapp; w.summary = !w.summary; save('WhatsApp summary ' + (w.summary ? 'on' : 'off'), 'Notifications'); });
  FF.act('st-wa-save', (f) => { Object.assign(FF.db.settings.whatsapp, { to: f.to, time: f.time }); save('Updated WhatsApp summary', 'Notifications'); });
  FF.act('st-plan', (d) => { if (FF.me().role !== 'OWNER') return FF.toast('Only the owner can change the plan', 'bad'); FF.confirm('Switch to ' + FF.cap(d.v.toLowerCase()) + '?', 'In the product this would go to billing and take effect from the next cycle. Here it changes straight away so you can see what unlocks.', 'Switch plan', () => { FF.db.org.plan = d.v; FF.db.settings.tryon.monthly = { LITE: 10, PRO: 100, PREMIUM: 300 }[d.v]; save('Plan → ' + d.v, 'Subscription'); }); });
  FF.act('st-addon', (d) => { const a = (FF.db.org.addons = FF.db.org.addons || []), i = a.indexOf(d.k); i < 0 ? a.push(d.k) : a.splice(i, 1); save('Add-on ' + (i < 0 ? 'requested' : 'removed'), d.k); });
  FF.act('st-audit-x', () => FF.download('audit-log.csv', FF.csv([['When', 'Who', 'Action', 'On', 'Detail']].concat(FF.db.audit.map((a) => [new Date(a.at).toISOString(), a.who, a.action, a.entity, a.detail])))));
  FF.act('st-flag', (d) => { const f = FF.db.settings.flags; f[d.k] = !f[d.k]; FF.save(); FF.render(); FF.toast('Scenario ' + (f[d.k] ? 'on' : 'off'), 'warn'); });
  FF.act('st-unlock', () => { FF.db.settings.pilot.locked = false; FF.save(); FF.toast('Thresholds unlocked for the demo', 'warn'); FF.go('#/pilot'); });
  FF.act('st-onb', () => { FF.db.settings.onboarded = false; FF.save(); FF.toast('The setup guide will open at the next owner sign-in', 'ok'); });
  FF.act('st-reset', () => FF.confirm('Reset all demo data?', 'Every visit, sale and setting returns to the starting demo. You will be signed out.', 'Reset', () => { FF.resetDemo(); location.hash = '#/home'; location.reload(); }, true));

  /* ---------- pitch kit ---------- */
  const PK = { tab: 'roi', aged: 1000000, lift: 3, margin: 40, mark: 20, plan: 4999 };
  FF.page('pitch', { title: 'Pitch kit', icon: 'spark', roles: R.MGR, render: () => { const ben = (PK.aged * PK.lift / 100) * ((PK.margin + PK.mark) / 100), sl = (k, label, min, max, step, fmt) => `<div class="field"><label>${label} <b class="num" style="float:right">${fmt(PK[k])}</b></label><input type="range" min="${min}" max="${max}" step="${step}" value="${PK[k]}" data-change="pk" data-k="${k}"></div>`;
    const body = { roi: `<div class="split"><div class="card col gap16"><h3>Dead-stock calculator ${U.badge('Illustrative', 'warn')}</h3>${sl('aged', 'Aged stock in the shop, at MRP', 200000, 5000000, 100000, FF.inrK)}${sl('lift', 'Extra aged stock sold each month', 1, 10, 0.5, (v) => v + '%')}${sl('margin', 'Margin earned on it', 20, 60, 5, (v) => v + '%')}${sl('mark', 'Markdown avoided', 0, 40, 5, (v) => v + '%')}${sl('plan', 'Plan price per month', 1499, 9999, 500, FF.inr)}</div><div class="card"><h4>Benefit per month</h4><div class="serif" style="font-size:52px;line-height:1.1" id="pk-ben">${FF.inr(ben)}</div><p class="muted" id="pk-sub">against a ${FF.inr(PK.plan)} plan · ${(ben / PK.plan).toFixed(1)}× the fee</p><hr><p class="small">${FF.inrK(PK.aged)} × ${PK.lift}% a month × (${PK.margin}% margin + ${PK.mark}% markdown avoided).</p><p class="note small mt12">This is arithmetic on assumptions, not a promise. The pilot's control group measures the real number — say so in the room.</p></div></div>`,
      demo: `<div class="card"><h3>The 7-minute demo</h3><p class="small muted">Laptop plus one tablet. Every synthetic number on screen is labelled.</p><ol class="tl mt16" style="padding-left:0">${[['0:00', 'The problem, three ways', 'Shopper’s time, about a quarter of shelf stock past its window, salesperson’s time.', ''], ['1:00', 'Be the shopper', 'Run a festive-saree consultation in Gujarati. Point at “why it suits you” and the size in stock.', 'kiosk.html?mode=assisted'], ['2:30', 'See it on me', 'Open the picks on a phone; show the consents and the AI label.', 'phone.html'], ['3:30', 'Be the salesperson', 'Claim the shopper from the live queue; rack codes and the “Say” line.', '#/queue'], ['4:30', 'Bill it', 'Scan the shopper’s QR at the counter; GST and receipt.', '#/billing'], ['5:30', 'Be the owner', 'Aged stock cleared, the control group, the buying list.', '#/insights'], ['6:30', 'The pilot offer', 'Six weeks, numbers agreed up front, nothing to pay if they are missed.', '#/pilot']].map(([t, h, d, l]) => `<li><b>${t} · ${h}</b>${l ? ` <a class="link small" href="${l}" ${l.endsWith('html') || l.includes('.html?') ? 'target="_blank" rel="noopener"' : ''}>open</a>` : ''}<div class="small muted">${d}</div></li>`).join('')}</ol></div>`,
      plans: `<p class="note small mb16">Hypotheses to test across the first 5–10 conversations — not a price list.</p><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Module</th><th>Lite</th><th>Pro</th><th>Premium</th><th>Sold separately</th></tr></thead><tbody>${[['Catalogue, intake, staff app, owner results', '✓', '✓', '✓', '—'], ['AI suggestions with clearance ranking', '✓', '✓', '✓', '—'], ['Shopper modes', 'QR / phone', '+ Assisted + Kiosk', 'All', 'Hardware rent or buy'], ['Use their billing software', 'Manual, Excel', 'Manual, Excel', '+ Tally bridge, cloud link', 'Connector setup ₹5–25k'], ['FitFirst Billing', 'Add-on ₹499–999', '✓', '✓', 'Printers and scanners'], ['Virtual try-on', 'Demo only', '~100 / month', '~300 / month', 'Extra packs'], ['AI catalogue photos', '—', '—', 'Some included', 'Per image'], ['We catalogue for you', '—', '—', 'Optional', 'Per piece or retainer'], ['Multi-store, WhatsApp summaries', '—', '—', '✓', '—'], ['Indicative price / month', '₹1,499–2,499', '₹3,999–5,999', '₹9,999+', '']].map((r) => `<tr>${r.map((c, i) => `<td class="${i ? 'small' : 'b'}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="card mt16"><h3>The pilot offer</h3><dl class="kv mt8 small"><dt>Scope</dt><dd>Aged stock plus key categories, 200–400 pieces</dd><dt>Length</dt><dd>6 weeks live, after the festival peak</dd><dt>Price</dt><dd>Free, or a refundable setup fee</dd><dt>Shop provides</dt><dd>Space, one staff champion, exports or billing access</dd><dt>We provide</dt><dd>Setup, the dead-stock cataloguing sprint, weekly reviews</dd><dt>Agreed in writing</dt><dd>Kill threshold, aged-stock measure, control group share, data terms</dd></dl></div>`,
      edge: `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Type</th><th>Examples</th><th>What they miss that FitFirst does</th></tr></thead><tbody>${[['Smart mirrors and virtual trial rooms', 'In-store try-on hardware vendors', 'Costly hardware for brands, centred on try-on. No “what suits you” ranking, no aged-stock engine, no phone-first tier, no billing.'], ['Catalogue and on-model tools', 'Online catalogue image tools', 'Built for web shops; they do not know who is standing in the store.'], ['Consumer styling apps', 'Personal styling apps', 'Not tied to this shop’s stock.'], ['Billing software', 'Counter billing and accounting packages', 'Record sales but do not create them. We work with them, or replace the counter.']].map((r) => `<tr><td class="b">${r[0]}</td><td class="small">${r[1]}</td><td class="small">${r[2]}</td></tr>`).join('')}</tbody></table></div><p class="note mt16"><b>The wedge:</b> suits you + in stock here + clears old stock — with ethnic-wear depth, at small-shop prices, with any billing software or ours.</p><p class="tiny muted mt8">Check every competitor claim against a current source before it goes in the deck.</p>` }[PK.tab];
    return `<div class="ph1"><div><h1>Pitch kit</h1><p>What you take into a shop owner's office. The discovery questions live in the <a class="link" href="#/onboarding">setup guide</a>.</p></div></div>${U.tabs('pk-tab', [['roi', 'Value calculator'], ['demo', 'Demo script'], ['plans', 'Plans and pilot offer'], ['edge', 'Why us']], PK.tab)}<div class="mt16">${body}</div>`; } });
  FF.act('pk-tab', (d) => { PK.tab = d.v; FF.render(); });
  FF.onChange('pk', (v, el) => { PK[el.dataset.k] = +v; const ben = (PK.aged * PK.lift / 100) * ((PK.margin + PK.mark) / 100); el.previousElementSibling.querySelector('b').textContent = { aged: FF.inrK, plan: FF.inr }[el.dataset.k] ? { aged: FF.inrK, plan: FF.inr }[el.dataset.k](+v) : v + '%'; $('#pk-ben').textContent = FF.inr(ben); $('#pk-sub').textContent = `against a ${FF.inr(PK.plan)} plan · ${(ben / PK.plan).toFixed(1)}× the fee`; });

  /* ---------- platform console (FitFirst's own team) ---------- */
  FF.page('platform', { title: 'FitFirst ops', icon: 'layers', roles: ['OWNER'], render: () => { const db = FF.db; return `<div class="ph1"><div><h1>FitFirst ops console</h1><p>${U.badge('Internal', 'ink')} What the FitFirst team sees across shops: tenants, the model registry and the platform-wide stops. Shown here so the whole product is visible in one prototype.</p></div></div>
      <div class="grid g4">${U.kpi('Shops', 3, '1 pilot · 2 in setup')}${U.kpi('AI spend this month', '₹4,180', 'tagging ₹310 · try-on ₹3,870')}${U.kpi('Try-on p50', '23 s', 'target 25 s or less')}${U.kpi('Isolation tests', 'Passing', 'shop A cannot read shop B')}</div>
      <div class="sec"><div class="sh"><h2>Shops</h2>${U.demo()}</div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Shop</th><th>Plan</th><th>Billing path</th><th>Live styles</th><th>Try-ons</th><th>Health</th></tr></thead><tbody><tr><td class="b">${esc(FF.store().name)}</td><td>${FF.cap(db.org.plan.toLowerCase())} · pilot</td><td>${db.settings.pos.path === 'B' ? 'FitFirst Billing' : 'Their software · ' + db.settings.pos.level}</td><td>${db.products.filter((p) => p.status === 'LIVE').length}</td><td>${db.settings.tryon.used} / ${db.settings.tryon.monthly}</td><td>${U.badge('Healthy', 'ok')}</td></tr><tr><td class="b">Rangmanch Sarees, Rajkot</td><td>Lite · setup</td><td>Their software · L1</td><td>212</td><td>0 / 10</td><td>${U.badge('Import in progress', 'info')}</td></tr><tr><td class="b">Navrang Menswear, Vadodara</td><td>Pro · setup</td><td>FitFirst Billing</td><td>96</td><td>4 / 100</td><td>${U.badge('CA review pending', 'warn')}</td></tr></tbody></table></div></div>
      <div class="sec"><div class="sh"><h2>Model registry</h2><span class="small muted">models are retired by their makers about once a year — this is where a swap is made safe</span></div><div class="card pad0">${db.models.map((m) => `<div class="row wrap" style="padding:12px 16px;border-bottom:1px solid var(--line)"><div class="grow" style="min-width:240px"><b>${esc(m.job)}</b> ${U.badge(FF.cap(m.status.toLowerCase()), m.status === 'ACTIVE' ? 'ok' : '')}<div class="small muted"><span class="mono">${esc(m.model)}</span> · ${esc(m.provider)}</div><div class="small">Evaluation: ${esc(m.eval)} · Retirement: ${esc(m.retire)}</div></div><button class="btn btn-s" data-act="pf-swap" data-id="${m.id}">Swap model…</button></div>`).join('')}</div></div>
      <div class="sec"><div class="sh"><h2>Platform stops</h2></div><div class="card">${row('Stop all try-on rendering', 'Every shop, immediately. For a provider incident or a runaway bill.', U.switch('pf-kill', db.platformKill))}${row('Monthly retirement check', 'Last run 3 Nov · next 3 Dec · 1 model on watch', `<button class="btn btn-s" data-act="pf-check">Run now</button>`)}</div></div>`; } });
  FF.act('pf-kill', () => { FF.db.platformKill = !FF.db.platformKill; FF.db.settings.tryon.kill = FF.db.platformKill; save('Platform try-on stop ' + (FF.db.platformKill ? 'on' : 'off'), 'Platform'); });
  FF.act('pf-check', () => FF.toast('No new retirement notices from providers', 'ok'));
  FF.act('pf-swap', (d) => { const m = FF.db.models.find((x) => x.id === d.id); FF.modal({ title: 'Swap model · ' + esc(m.job), size: 'narrow', body: `<form data-submit="pf-swap-run" class="col"><input type="hidden" name="id" value="${m.id}">${U.field('New model ID', `<input name="model" required minlength="4" placeholder="${esc(m.model)}">`, 'The fixed evaluation set is re-run before the swap can go live')}<button class="btn btn-p">Run the evaluation set</button></form>` }); });
  FF.act('pf-swap-run', (f) => { const m = FF.db.models.find((x) => x.id === f.id); FF.reOverlay({ title: 'Running evaluation…', body: `<div class="center"><div class="spin" style="margin:12px auto"></div><p class="small muted">150 stylist-labelled garments · same prompts, new model</p></div>` }); setTimeout(() => { const score = 86 + Math.floor(Math.random() * 9), ok = score >= 90; if (!$('.modal')) return; FF.reOverlay({ title: ok ? 'Passed — ready to switch' : 'Below the bar — not switched', body: `<p><span class="mono">${esc(f.model)}</span> scored <b>${score}%</b> on category and silhouette (target 90%).</p><p class="small muted mt8">${ok ? 'Shops will use it from the next request. The old model stays as a fallback for 7 days.' : 'The current model stays active. Nothing changed for any shop.'}</p>`, footer: `<button class="btn btn-p" data-act="close">Close</button>` }); if (ok) { m.model = f.model; m.eval = `category ${score}% · re-run today`; save('Swapped model', m.job, f.model); const s = FF.$$('.scrim').pop(); if (!s) FF.modal({ title: 'Switched', body: '' }); } }, 1600); });
})();
